INSERT INTO transcriptsegment VALUES(1,1,'s1',0,'Asha',0.0,9.0,'Let''s plan the payments release. Rahul, please finish the refund API by Thursday.',1,'import:json');
INSERT INTO transcriptsegment VALUES(2,1,'s2',1,'Rahul',9.0,14.0,'Okay, I will have the refund API done by Thursday.',1,'import:json');
INSERT INTO transcriptsegment VALUES(3,1,'s3',2,'Asha',14.0,22.0,'Priya, once the refund API is ready, you will run the regression tests.',1,'import:json');
INSERT INTO transcriptsegment VALUES(4,1,'s4',3,'Priya',22.0,28.0,'Sure, I''ll start regression testing after Rahul''s API is merged.',1,'import:json');
INSERT INTO transcriptsegment VALUES(5,1,'s5',4,'Asha',28.0,39.0,'We decided to keep Stripe as the payment provider, because switching now would delay the release by two weeks.',1,'import:json');
INSERT INTO transcriptsegment VALUES(6,1,'s6',5,'SPEAKER_03',39.0,44.0,'I can update the release notes by Friday.',1,'import:json');
INSERT INTO transcriptsegment VALUES(7,1,'s7',6,'Asha',44.0,50.0,'Maybe someone should look into the flaky login test at some point.',1,'import:json');
INSERT INTO transcriptsegment VALUES(8,1,'s8',7,'Asha',50.0,58.0,'Open question: do we need finance sign-off before enabling refunds for all users?',1,'import:json');
INSERT INTO transcriptsegment VALUES(9,2,'s1',0,'Asha',0.0,4.0,'Quick update on the refund API task.',1,'import:json');
INSERT INTO transcriptsegment VALUES(10,2,'s2',1,'Rahul',4.0,8.0,'The refund API is done and merged.',1,'import:json');
INSERT INTO transcriptsegment VALUES(11,2,'s3',2,'Asha',8.0,18.0,'Priya is travelling, so Samiksha takes over the regression tests, due Monday, October 26.',1,'import:json');
INSERT INTO transcriptsegment VALUES(12,2,'s4',3,'Samiksha',18.0,22.0,'Yes, I''ll own the regression tests.',1,'import:json');
INSERT INTO transcriptsegment VALUES(13,2,'s5',4,'Asha',22.0,27.0,'Also, cancel the old release notes plan.',1,'import:json');
INSERT INTO transcriptsegment VALUES(14,2,'s6',5,'Asha',27.0,31.0,'Rahul, can you prepare the rollback runbook?',1,'import:json');
INSERT INTO transcriptsegment VALUES(15,2,'s7',6,'Rahul',31.0,36.0,'Yes, I''ll write the rollback runbook by Saturday.',1,'import:json');
INSERT INTO transcriptsegment VALUES(16,3,'s1',0,'Asha',0.0,4.0,'Regression testing status enu? Samiksha?',1,'import:json');
INSERT INTO transcriptsegment VALUES(17,3,'s2',1,'Samiksha',4.0,10.0,'Testing almost mugidide, naale finish maadthini.',1,'import:json');
INSERT INTO transcriptsegment VALUES(18,3,'s3',2,'Rahul',10.0,16.0,'Rollback runbook ready hai, maine kal hi complete kar diya.',1,'import:json');
INSERT INTO transcriptsegment VALUES(19,3,'s4',3,'Asha',16.0,24.0,'Sari, finance sign-off bagge Priya follow up maadli, Wednesday olage.',1,'import:json');
INSERT INTO transcriptsegment VALUES(20,3,'s5',4,'Priya',24.0,30.0,'Theek hai, main Wednesday tak finance team se baat kar lungi.',1,'import:json');
INSERT INTO transcriptsegment VALUES(21,4,'s1',0,'SPEAKER_00',0.0,3.160000000000000142,'Okay team, quicksync on the mobile app launch.',1,'stt:whisper-local');
INSERT INTO transcriptsegment VALUES(22,4,'s2',1,'SPEAKER_00',3.799999999999999823,6.919999999999999929,'Kavya, please finish the login screen by friday.',1,'stt:whisper-local');
INSERT INTO transcriptsegment VALUES(23,4,'s3',2,'SPEAKER_00',7.519999999999999574,11.16000000000000014,'तीख है, मैं लाजिन स्क्रवार तक पूरा कर दूंगी.',1,'stt:whisper-local');
INSERT INTO transcriptsegment VALUES(24,4,'s4',3,'SPEAKER_00',11.75999999999999979,14.11999999999999922,'The payment API is done and merged.',1,'stt:whisper-local');
INSERT INTO transcriptsegment VALUES(25,4,'s5',4,'SPEAKER_00',14.72000000000000063,19.92000000000000171,'Great! Meera, once the payment API is live, start the release notes.',1,'stt:whisper-local');
INSERT INTO transcriptsegment VALUES(26,4,'s6',5,'SPEAKER_00',20.51999999999999958,23.9200000000000017,'सरी, नानु नाले, release notes शुरु माडते नी.',1,'stt:whisper-local');
CREATE TABLE llmrun (
	id INTEGER NOT NULL, 
	meeting_id INTEGER, 
	purpose VARCHAR NOT NULL, 
	provider VARCHAR NOT NULL, 
	model VARCHAR NOT NULL, 
	temperature FLOAT NOT NULL, 
	seed INTEGER, 
	latency_ms INTEGER NOT NULL, 
	attempts INTEGER NOT NULL, 
	usage JSON, 
	raw_text VARCHAR NOT NULL, 
	error VARCHAR, 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(meeting_id) REFERENCES meeting (id)
);
