INSERT INTO llmrun VALUES(2,1,'minutes','ollama','qwen3:8b',0.0,7,80662,1,'{"prompt_tokens": 517, "output_tokens": 374, "eval_seconds": 67.32}',unistr('{\u000a  "summary": "The team discussed the release plan for the payments feature, focusing on the refund API, regression testing, and payment provider selection. They also raised an open question about finance sign-off for refunds.",\u000a  "discussion": [\u000a    {\u000a      "topic": "Refund API and Testing",\u000a      "summary": "Asha assigned Rahul to complete the refund API by Thursday. Priya will run regression tests once the API is merged.",\u000a      "segment_ids": ["s1", "s2", "s3", "s4"]\u000a    },\u000a    {\u000a      "topic": "Payment Provider Selection",\u000a      "summary": "The team decided to keep Stripe as the payment provider to avoid a two-week delay in the release.",\u000a      "segment_ids": ["s5"]\u000a    },\u000a    {\u000a      "topic": "Release Notes and Flaky Test",\u000a      "summary": "SPEAKER_03 offered to update the release notes by Friday. Asha suggested looking into the flaky login test at some point.",\u000a      "segment_ids": ["s6", "s7"]\u000a    }\u000a  ],\u000a  "decisions": [\u000a    {\u000a      "text": "Rahul will complete the refund API by Thursday.",\u000a      "segment_ids": ["s1", "s2"]\u000a    },\u000a    {\u000a      "text": "Priya will run regression tests after the refund API is merged.",\u000a      "segment_ids": ["s3", "s4"]\u000a    },\u000a    {\u000a      "text": "Stripe will remain the payment provider to avoid a two-week delay.",\u000a      "segment_ids": ["s5"]\u000a    }\u000a  ],\u000a  "open_questions": [\u000a    {\u000a      "text": "Do we need finance sign-off before enabling refunds for all users?",\u000a      "segment_ids": ["s8"]\u000a    }\u000a  ]\u000a}'),NULL,'2026-10-22 17:23:10.468463');
