INSERT INTO llmrun VALUES(6,2,'minutes','ollama','qwen3:8b',0.0,7,89822,1,'{"prompt_tokens": 522, "output_tokens": 373, "eval_seconds": 69.04}',unistr('{\u000a  "summary": "Asha provided an update on the refund API task, confirming it is complete and merged. Samiksha will take over regression testing due to Priya''s travel, with the task due by Monday, October 26. Asha also requested cancellation of the old release notes plan. Rahul will prepare the rollback runbook by Saturday.",\u000a  "discussion": [\u000a    {\u000a      "topic": "Refund API Status",\u000a      "summary": "The refund API has been completed and merged into the main branch.",\u000a      "segment_ids": ["s1", "s2"]\u000a    },\u000a    {\u000a      "topic": "Regression Testing Ownership",\u000a      "summary": "Samiksha will take over regression testing due to Priya''s travel, with the task due by Monday, October 26.",\u000a      "segment_ids": ["s3", "s4"]\u000a    },\u000a    {\u000a      "topic": "Release Notes Plan",\u000a      "summary": "Asha requested cancellation of the old release notes plan.",\u000a      "segment_ids": ["s5"]\u000a    },\u000a    {\u000a      "topic": "Rollback Runbook",\u000a      "summary": "Rahul will prepare the rollback runbook by Saturday.",\u000a      "segment_ids": ["s6", "s7"]\u000a    }\u000a  ],\u000a  "decisions": [\u000a    {\u000a      "text": "Samiksha will own the regression tests.",\u000a      "segment_ids": ["s3", "s4"]\u000a    },\u000a    {\u000a      "text": "The old release notes plan will be cancelled.",\u000a      "segment_ids": ["s5"]\u000a    },\u000a    {\u000a      "text": "Rahul will prepare the rollback runbook by Saturday.",\u000a      "segment_ids": ["s6", "s7"]\u000a    }\u000a  ],\u000a  "open_questions": []\u000a}'),NULL,'2026-10-22 17:38:33.369085');
