CREATE TABLE task (
	id INTEGER NOT NULL, 
	code VARCHAR NOT NULL, 
	title VARCHAR NOT NULL, 
	deliverable VARCHAR, 
	owner VARCHAR, 
	owner_certainty VARCHAR NOT NULL, 
	due_date VARCHAR, 
	deadline_raw VARCHAR, 
	deadline_kind VARCHAR NOT NULL, 
	timezone VARCHAR NOT NULL, 
	priority VARCHAR, 
	priority_basis VARCHAR, 
	status VARCHAR NOT NULL, 
	blocked_reason VARCHAR, 
	revision INTEGER NOT NULL, 
	origin_meeting_id INTEGER NOT NULL, 
	last_meeting_id INTEGER, 
	approved BOOLEAN NOT NULL, 
	evidence JSON, 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(origin_meeting_id) REFERENCES meeting (id)
);
