CREATE TABLE summaryshare (
	id INTEGER NOT NULL, 
	meeting_id INTEGER NOT NULL, 
	content VARCHAR NOT NULL, 
	channel VARCHAR NOT NULL, 
	recipients JSON, 
	state VARCHAR NOT NULL, 
	approval_id INTEGER, 
	sent_at DATETIME, 
	error VARCHAR, 
	created_at DATETIME NOT NULL, 
