CREATE TABLE commitmentevent (
	id INTEGER NOT NULL, 
	meeting_id INTEGER NOT NULL, 
	llm_run_id INTEGER, 
	seq INTEGER NOT NULL, 
	type VARCHAR NOT NULL, 
	task_key VARCHAR, 
	payload JSON, 
	segment_ids JSON, 
	target_task_id VARCHAR, 
	interpretation_status VARCHAR NOT NULL, 
	rejection_reason VARCHAR, 
	PRIMARY KEY (id), 
	FOREIGN KEY(meeting_id) REFERENCES meeting (id), 
	FOREIGN KEY(llm_run_id) REFERENCES llmrun (id)
);
