CREATE TABLE taskdependency (
	id INTEGER NOT NULL, 
	prerequisite_task_id INTEGER NOT NULL, 
	dependent_task_id INTEGER NOT NULL, 
	type VARCHAR NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (prerequisite_task_id, dependent_task_id), 
	FOREIGN KEY(prerequisite_task_id) REFERENCES task (id), 
	FOREIGN KEY(dependent_task_id) REFERENCES task (id)
);
INSERT INTO taskdependency VALUES(1,1,2,'finish_to_start');
CREATE TABLE calendarevent (
	id INTEGER NOT NULL, 
	task_id INTEGER NOT NULL, 
	uid VARCHAR NOT NULL, 
	title VARCHAR NOT NULL, 
	date VARCHAR NOT NULL, 
	timezone VARCHAR NOT NULL, 
	sync_state VARCHAR NOT NULL, 
	external_provider VARCHAR, 
	external_id VARCHAR, 
	approval_id INTEGER, 
	sequence INTEGER NOT NULL, 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(task_id) REFERENCES task (id)
);
