CREATE TABLE notification (
	id INTEGER NOT NULL, 
	reminder_id INTEGER, 
	task_id INTEGER, 
	message VARCHAR NOT NULL, 
	read BOOLEAN NOT NULL, 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(reminder_id) REFERENCES reminder (id), 
	FOREIGN KEY(task_id) REFERENCES task (id)
