CREATE TABLE IF NOT EXISTS 'memory_fts_content'(id INTEGER PRIMARY KEY, c0, c1, c2, c3);
INSERT INTO memory_fts_content VALUES(1,'segment','seg:1:s1',1,'Let''s plan the payments release. Rahul, please finish the refund API by Thursday.');
INSERT INTO memory_fts_content VALUES(2,'segment','seg:1:s2',1,'Okay, I will have the refund API done by Thursday.');
INSERT INTO memory_fts_content VALUES(3,'segment','seg:1:s3',1,'Priya, once the refund API is ready, you will run the regression tests.');
INSERT INTO memory_fts_content VALUES(4,'segment','seg:1:s4',1,'Sure, I''ll start regression testing after Rahul''s API is merged.');
INSERT INTO memory_fts_content VALUES(5,'segment','seg:1:s5',1,'We decided to keep Stripe as the payment provider, because switching now would delay the release by two weeks.');
INSERT INTO memory_fts_content VALUES(6,'segment','seg:1:s6',1,'I can update the release notes by Friday.');
INSERT INTO memory_fts_content VALUES(7,'segment','seg:1:s7',1,'Maybe someone should look into the flaky login test at some point.');
INSERT INTO memory_fts_content VALUES(8,'segment','seg:1:s8',1,'Open question: do we need finance sign-off before enabling refunds for all users?');
INSERT INTO memory_fts_content VALUES(9,'question','q:1',1,'Open question: Do we need finance sign-off before enabling refunds for all users?');
INSERT INTO memory_fts_content VALUES(12,'task','task:TASK-3',1,'TASK-3 Update the release notes. Owner Meera. Status todo. Due 2026-10-23.');
INSERT INTO memory_fts_content VALUES(13,'decision','dec:1',1,'Decision: Keep Stripe as the payment provider');
INSERT INTO memory_fts_content VALUES(14,'segment','seg:2:s1',2,'Quick update on the refund API task.');
INSERT INTO memory_fts_content VALUES(15,'segment','seg:2:s2',2,'The refund API is done and merged.');
INSERT INTO memory_fts_content VALUES(16,'segment','seg:2:s3',2,'Priya is travelling, so Samiksha takes over the regression tests, due Monday, October 26.');
INSERT INTO memory_fts_content VALUES(17,'segment','seg:2:s4',2,'Yes, I''ll own the regression tests.');
INSERT INTO memory_fts_content VALUES(18,'segment','seg:2:s5',2,'Also, cancel the old release notes plan.');
INSERT INTO memory_fts_content VALUES(19,'segment','seg:2:s6',2,'Rahul, can you prepare the rollback runbook?');
INSERT INTO memory_fts_content VALUES(20,'segment','seg:2:s7',2,'Yes, I''ll write the rollback runbook by Saturday.');
INSERT INTO memory_fts_content VALUES(21,'task','task:TASK-2',1,'TASK-2 Run regression tests. Owner Samiksha. Status todo. Due 2026-10-26.');
INSERT INTO memory_fts_content VALUES(22,'task','task:TASK-4',2,'TASK-4 Prepare the rollback runbook. Owner Rahul. Status todo. Due 2026-10-24.');
INSERT INTO memory_fts_content VALUES(23,'decision','dec:2',2,'Decision: Samiksha will own the regression tests.');
INSERT INTO memory_fts_content VALUES(24,'decision','dec:3',2,'Decision: The old release notes plan will be cancelled.');
INSERT INTO memory_fts_content VALUES(25,'decision','dec:4',2,'Decision: Rahul will prepare the rollback runbook by Saturday.');
INSERT INTO memory_fts_content VALUES(26,'task','task:TASK-1',1,'TASK-1 Finish the refund API. Owner Rahul. Status done. Due 2026-10-22.');
INSERT INTO memory_fts_content VALUES(27,'segment','seg:3:s1',3,'Regression testing status enu? Samiksha?');
INSERT INTO memory_fts_content VALUES(28,'segment','seg:3:s2',3,'Testing almost mugidide, naale finish maadthini.');
INSERT INTO memory_fts_content VALUES(29,'segment','seg:3:s3',3,'Rollback runbook ready hai, maine kal hi complete kar diya.');
INSERT INTO memory_fts_content VALUES(30,'segment','seg:3:s4',3,'Sari, finance sign-off bagge Priya follow up maadli, Wednesday olage.');
INSERT INTO memory_fts_content VALUES(31,'segment','seg:3:s5',3,'Theek hai, main Wednesday tak finance team se baat kar lungi.');
INSERT INTO memory_fts_content VALUES(32,'segment','seg:4:s1',4,'Okay team, quicksync on the mobile app launch.');
INSERT INTO memory_fts_content VALUES(33,'segment','seg:4:s2',4,'Kavya, please finish the login screen by friday.');
INSERT INTO memory_fts_content VALUES(34,'segment','seg:4:s3',4,'तीख है, मैं लाजिन स्क्रवार तक पूरा कर दूंगी.');
INSERT INTO memory_fts_content VALUES(35,'segment','seg:4:s4',4,'The payment API is done and merged.');
INSERT INTO memory_fts_content VALUES(36,'segment','seg:4:s5',4,'Great! Meera, once the payment API is live, start the release notes.');
INSERT INTO memory_fts_content VALUES(37,'segment','seg:4:s6',4,'सरी, नानु नाले, release notes शुरु माडते नी.');
